def transform(grid):
    """Tile the non-rectangular pattern from the grid's pattern cell throughout
    every cell, recoloring each tile from its row band's left marker."""
    h, w = len(grid), len(grid[0])
    # Identify full-color horizontal and vertical separators.
    div_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0]
    div_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    row_edges = [-1] + div_rows + [h]
    col_edges = [-1] + div_cols + [w]
    row_bands = [(row_edges[i] + 1, row_edges[i + 1]) for i in range(len(row_edges) - 1)]
    col_bands = [(col_edges[i] + 1, col_edges[i + 1]) for i in range(len(col_edges) - 1)]

    # The pattern is the non-rectangular occupied shape in a cell right of
    # the marker column. Keep its coordinates relative to the cell origin.
    shape = None
    for r0, r1 in row_bands:
        for c0, c1 in col_bands[1:]:
            occupied = [(r-r0, c-c0) for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != 0]
            if not occupied:
                continue
            rs = [r for r, _ in occupied]
            cs = [c for _, c in occupied]
            if len(occupied) != (max(rs)-min(rs)+1) * (max(cs)-min(cs)+1):
                shape = occupied
                break
        if shape is not None:
            break
    if shape is None:
        raise ValueError("No non-rectangular pattern cell found")

    # Preserve separator lines, clear cell contents, then replicate shape.
    out = [[0 for _ in range(w)] for _ in range(h)]
    for r in div_rows:
        out[r] = grid[r][:]
    for c in div_cols:
        for r in range(h):
            out[r][c] = grid[r][c]
    for r0, r1 in row_bands:
        markers = [grid[r][c] for r in range(r0, r1)
                   for c in range(col_bands[0][0], col_bands[0][1]) if grid[r][c] != 0]
        if not markers:
            continue
        color = markers[0]
        for c0, c1 in col_bands:
            for dr, dc in shape:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = color
    return out
